(4288674, 615331, 66267, '<td valign="top">great job except for the eyes. The blue looks way too fake.<br/> <br/>I''d love this as a pure black and white.</td>', 'great job except for the eyes. The blue looks way too fake. I''d love this as a pure black and white.', '2007-12-04 15:38:21.000000', NULL, 1),
(4288738, 615175, 50598, '<td valign="top">Might need a nudge of more contrast.</td>', 'Might need a nudge of more contrast.', '2007-12-04 16:19:08.000000', NULL, 1),
(4288746, 618400, 50598, '<td valign="top">OMG... THE CLOUDS ARE EATING THAT CITY!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!</td>', 'OMG... THE CLOUDS ARE EATING THAT CITY!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!', '2007-12-04 16:24:37.000000', NULL, 1),
(4288780, 618346, 50598, '<td valign="top">nice 7</td>', 'nice 7', '2007-12-04 16:34:21.000000', NULL, 1),
