(4299506, 609209, 83313, '<td valign="top">A good shot of this person, but it  not stand out to me.</td>', 'A good shot of this person, but it  not stand out to me.', '2007-12-07 16:27:54.000000', NULL, 1),
(4299510, 618443, 83313, '<td valign="top">Is he a Monk, or just someone with a hoodie napping? Nice lighting.</td>', 'Is he a Monk, or just someone with a hoodie napping? Nice lighting.', '2007-12-07 16:29:08.000000', NULL, 1),
(4299514, 617849, 83313, '<td valign="top">This is just cool looking. I like the perspective.</td>', 'This is just cool looking. I like the perspective.', '2007-12-07 16:30:10.000000', NULL, 1),
(4299517, 618026, 83313, '<td valign="top">Contrast could be better, it would help bring out that mist in the distance. Composition divides me between the branch and the opposite bank.</td>', 'Contrast could be better, it would help bring out that mist in the distance. Composition divides me between the branch and the opposite bank.', '2007-12-07 16:31:44.000000', NULL, 1),
(4299522, 618119, 83313, '<td valign="top">Very, very good. Awesome detail and the compsition leads me right to the barn. I would love to see this at a better resolution.</td>', 'Very, very good. Awesome detail and the compsition leads me right to the barn. I would love to see this at a better resolution.', '2007-12-07 16:33:38.000000', NULL, 1),
(4299523, 618352, 83313, '<td valign="top">Her features seem washed out, though that may have been the effect you were going for.</td>', 'Her features seem washed out, though that may have been the effect you were going for.', '2007-12-07 16:34:30.000000', NULL, 1),
(4299540, 612936, 83313, '<td valign="top">How close did these guys let you get? Looks like he is trying to scare you off.</td>', 'How close did these guys let you get? Looks like he is trying to scare you off.', '2007-12-07 16:43:24.000000', NULL, 1),
