(4299566, 618196, 78455, '<td valign="top">I''ll be very suprised if your image doesn''t beat mine, and on current scores mine''s heading for a top 5 finish! Good luck, hope you ribbon.</td>', 'I''ll be very suprised if your image doesn''t beat mine, and on current scores mine''s heading for a top 5 finish! Good luck, hope you ribbon.', '2007-12-07 16:56:39.000000', NULL, 1),
(4299574, 613108, 19961, '<td valign="top">5</td>', '5', '2007-12-07 17:00:50.000000', NULL, 1),
(4299590, 608659, 78455, '<td valign="top">I thought you''d go with this one mark - beautifull image! Will do very well, perhaps another ribbon!!! Definatelly deserves it.</td>', 'I thought you''d go with this one mark - beautifull image! Will do very well, perhaps another ribbon!!! Definatelly deserves it.', '2007-12-07 17:11:00.000000', NULL, 1),
(4299640, 618585, 67697, '<td valign="top">This is beautiful.  What great timing.  Love the expression on the matador''s face.</td>', 'This is beautiful.  What great timing.  Love the expression on the matador''s face.', '2007-12-07 17:28:47.000000', NULL, 1),
(4299642, 617002, 67697, '<td valign="top">This is awesome.  I love the dark tones and the reflection captured in the window.  Too bad she does not have an engagement ring on because that would have looked really pretty in the window too.  Great juxtaposition with the older couple down the street.  9</td>', 'This is awesome.  I love the dark tones and the reflection captured in the window.  Too bad she does not have an engagement ring on because that would have looked really pretty in the window too.  Great juxtaposition with the older couple down the street.  9', '2007-12-07 17:30:36.000000', NULL, 1),
(4299643, 615638, 67697, '<td valign="top">There''s something very magical about this picture.  Love it.</td>', 'There''s something very magical about this picture.  Love it.', '2007-12-07 17:31:06.000000', NULL, 1),
(4299660, 609975, 86379, '<td valign="top">Very pretty.</td>', 'Very pretty.', '2007-12-07 17:38:24.000000', NULL, 1),
(4299693, 609542, 50695, '<td valign="top">excellent composition, creating an exciting shape where none exists in 3 dimensions. everything in the photo works in service to that shape.</td>', 'excellent composition, creating an exciting shape where none exists in 3 dimensions. everything in the photo works in service to that shape.', '2007-12-07 17:54:18.000000', NULL, 1),
(4299696, 615836, 50695, '<td valign="top">wonderful capture! the divine moment... I mean the decisive moment.</td>', 'wonderful capture! the divine moment... I mean the decisive moment.', '2007-12-07 17:54:47.000000', NULL, 1),
