(4299727, 618476, 86379, '<td valign="top">Wow I love this one.</td>', 'Wow I love this one.', '2007-12-07 18:01:23.000000', NULL, 1),
(4299736, 616201, 86379, '<td valign="top">What a beautiful little face!</td>', 'What a beautiful little face!', '2007-12-07 18:03:43.000000', NULL, 1),
(4299742, 616972, 50695, '<td valign="top">a unique photo, and a meditation on beauty and ugliness. the ugliest part of the beautiful swan, yet in the classic S-shape the swan is know for. Look up "line of beauty" if you don''t already know the term.</td>', 'a unique photo, and a meditation on beauty and ugliness. the ugliest part of the beautiful swan, yet in the classic S-shape the swan is know for. Look up "line of beauty" if you don''t already know the term.', '2007-12-07 18:05:27.000000', NULL, 1),
(4299749, 618518, 50695, '<td valign="top">great capture of a moment perfectly balanced in time</td>', 'great capture of a moment perfectly balanced in time', '2007-12-07 18:06:54.000000', NULL, 1),
(4299755, 617847, 50695, '<td valign="top">very pleasing tones and composition</td>', 'very pleasing tones and composition', '2007-12-07 18:08:19.000000', NULL, 1),
